(function(){
 if(window.__SCOTTY_SCOTTISH_HUD_V1__)return;
 window.__SCOTTY_SCOTTISH_HUD_V1__=true;
 // Scottish audio is generated by the user's free local F5 worker through the existing Eyes On test bridge.
 const base='/api/voice/scottish';
 const $=id=>document.querySelector(id);
 function setStatus(v){const el=$('#vs');if(el)el.textContent=v}
 function setCommand(v){const el=$('#cs');if(el)el.textContent=v}
 async function responseError(r){
  let j={};try{j=await r.json()}catch{}
  return new Error(String(j.error||j.detail||('HTTP '+r.status)).slice(0,250));
 }
 let generation=0,active=null,player=null,voiceState='READY',pendingPlayback=null,progressTimer=null,voiceMode='fast';
 const audioEl=document.createElement('audio');audioEl.setAttribute('playsinline','');audioEl.style.display='none';document.body.appendChild(audioEl);
 function showPlayButton(show){
  let btn=document.getElementById('scottyPlayReadyAudio');
  if(!btn){btn=document.createElement('button');btn.id='scottyPlayReadyAudio';btn.textContent='▶ PLAY SCOTTISH VOICE';btn.style.cssText='display:none;width:100%;margin-top:8px;background:#12313b;color:#b8f9f0;border:1px solid #58a8b1;padding:10px;border-radius:8px;font-weight:bold';btn.onclick=()=>{if(pendingPlayback)pendingPlayback()};const panel=$('#voiceSettings');if(panel)panel.appendChild(btn)}
  btn.style.display=show?'block':'none';
 }
 // iPad Safari requires audio playback to originate from a user gesture.
 // A reusable audio element is activated by the TEST tap; delayed playback has a tap-to-play fallback.
 function primeAudio(){
  try{
   audioEl.muted=true;
   const p=audioEl.play();
   if(p&&p.then)p.then(()=>{audioEl.pause();audioEl.muted=false}).catch(()=>{audioEl.muted=false});
  }catch(e){audioEl.muted=false}
 }
 document.addEventListener('pointerdown',e=>{if(e.target.closest('#testVoice'))primeAudio()},true);

 const sleep=ms=>new Promise(r=>setTimeout(r,ms));
 function state(value){
  voiceState=value;
  setStatus('SCOTTISH VOICE '+value);
  const badge=document.getElementById('scottyVoiceQueueStatus');
  if(badge)badge.textContent='VOICE: '+value;
  const test=$('#testVoice');if(test)test.textContent=value==='GENERATING'||value==='SPEAKING'||value==='BUSY'?'REPLACE VOICE TEST':'TEST SCOTTISH VOICE';
 }
 function stopCurrent(){
  try{window.speechSynthesis?.cancel()}catch{}
  if(progressTimer){clearInterval(progressTimer);progressTimer=null}
  pendingPlayback=null;showPlayButton(false);
  if(active){active.abort();active=null}
  if(player){try{player.pause();player.src=''}catch{}player=null}
 }
 async function queueRequest(text,signal){
  // The local F5 engine is single-worker. A full queue means retry the latest phrase,
  // never submit parallel jobs or create a backlog of obsolete utterances.
  for(let attempt=0;attempt<7;attempt++){
   if(signal.aborted)throw new DOMException('Superseded','AbortError');
   const r=await fetch(base+'/speak',{method:'POST',credentials:'include',headers:{'content-type':'application/json'},body:JSON.stringify({text:text.slice(0,190)}),signal});
   if(r.ok){const j=await r.json();if(!j.job_id)throw Error('Scottish queue returned no job ID');return j.job_id}
   const err=await responseError(r);
   if(r.status!==429&&!/queue full|busy/i.test(err.message))throw err;
   state('BUSY');setCommand('VOICE BUSY • WAITING FOR LOCAL WORKER');
   if(attempt===6)throw Error('Local Scottish voice queue remains full. Wait for old jobs to finish.');
   await sleep(2500+attempt*1500);
  }
 }
 async function playScottish(text,seq,controller){
  const signal=controller.signal;
  const jobId=await queueRequest(text,signal);
  state('GENERATING');setCommand('VOICE GENERATING');
  const started=Date.now();
  if(progressTimer)clearInterval(progressTimer);
  progressTimer=setInterval(()=>{
   if(seq!==generation){clearInterval(progressTimer);progressTimer=null;return}
   const elapsed=Math.floor((Date.now()-started)/1000);
   if(voiceState==='GENERATING'){
    setStatus('SCOTTISH VOICE GENERATING • '+elapsed+'S');
    const msg=$('#voiceMsg');
    if(msg)msg.textContent=elapsed<180?'Scottish F5 CPU generating audio ('+elapsed+' seconds).':'Generation is taking unusually long ('+elapsed+' seconds). Check the local worker.';
   }
  },1000);
  for(let n=0;n<160;n++){
   if(signal.aborted||seq!==generation)throw new DOMException('Superseded','AbortError');
   await sleep(1200);
   const r=await fetch(base+'/jobs/'+encodeURIComponent(jobId),{credentials:'include',cache:'no-store',signal});
   if(!r.ok)throw await responseError(r);
   const x=await r.json();
   if(x.state==='error')throw Error(x.error||'Scottish voice generation failed');
   if(x.state==='complete'){
    if(progressTimer){clearInterval(progressTimer);progressTimer=null}
    const audio=await fetch(base+'/jobs/'+encodeURIComponent(jobId)+'/audio',{credentials:'include',signal});
    if(!audio.ok)throw await responseError(audio);
    const blob=await audio.blob();
    if(!blob.size)throw Error('Scottish audio empty');
    if(signal.aborted||seq!==generation)throw new DOMException('Superseded','AbortError');
    const url=URL.createObjectURL(blob);
    try{
     await new Promise((resolve,reject)=>{
      const a=audioEl;player=a;a.pause();a.src=url;a.muted=false;a.volume=1;
      let done=false;
      const finish=e=>{if(done)return;done=true;clearTimeout(timer);a.onended=null;a.onerror=null;pendingPlayback=null;showPlayButton(false);if(player===a)player=null;e?reject(e):resolve()};
      const timer=setTimeout(()=>finish(Error('Playback timed out')),180000);
      signal.addEventListener('abort',()=>{a.pause();finish(new DOMException('Superseded','AbortError'))},{once:true});
      a.onended=()=>finish();a.onerror=()=>finish(Error('Playback failed'));
      const begin=()=>{
       if(signal.aborted||seq!==generation)return finish(new DOMException('Superseded','AbortError'));
       pendingPlayback=null;showPlayButton(false);state('SPEAKING');setCommand('SPEAKING');
       const p=a.play();
       if(p&&p.catch)p.catch(e=>{
        if(e?.name==='NotAllowedError'){
         state('READY TO PLAY');setCommand('TAP PLAY TO HEAR SCOTTY');
         pendingPlayback=begin;showPlayButton(true);
        }else finish(e);
       });
      };
      begin();
     });
    }finally{URL.revokeObjectURL(url)}
    return;
   }
  }
  throw Error('Scottish voice generation timed out');
 }
 function browserVoice(text,seq){
  return new Promise((resolve,reject)=>{
   if(!('speechSynthesis' in window)){reject(Error('Browser speech is unavailable'));return}
   const engine=window.speechSynthesis;
   const utterance=new SpeechSynthesisUtterance(text);
   utterance.lang='en-GB';utterance.rate=1.04;utterance.pitch=0.94;
   const voices=engine.getVoices();
   const voice=voices.find(v=>/scottish|scotland|en-GB.*(fiona|daniel)/i.test(v.name))||
     voices.find(v=>v.lang==='en-GB')||voices.find(v=>v.lang.startsWith('en'));
   if(voice)utterance.voice=voice;
   const watchdog=setTimeout(()=>{if(seq===generation){state('TAP TO ENABLE AUDIO');setCommand('TAP VOICE TEST TO ENABLE AUDIO')}resolve()},4500);
   utterance.onstart=()=>{clearTimeout(watchdog);if(seq===generation){state('SPEAKING');setCommand('SPEAKING')}};
   utterance.onend=()=>{clearTimeout(watchdog);resolve()};
   utterance.onerror=e=>{clearTimeout(watchdog);reject(Error('Browser voice: '+(e.error||'unavailable')))};
   try{engine.cancel();engine.speak(utterance)}catch(e){clearTimeout(watchdog);reject(e)}
  })
 }
 speak=async function(text){
  text=String(text||'').trim();if(!text)return;
  const seq=++generation;
  stopCurrent();
  const controller=new AbortController();active=controller;
  speaking=true;state('GENERATING');setCommand('SCOTTISH VOICE');
  try{
   if(voiceMode==='fast')await browserVoice(text,seq);else await playScottish(text,seq,controller);
   if(seq===generation){state(voiceArmed?'LISTENING':'READY');setCommand(voiceArmed?'LISTENING':'READY')}
  }catch(e){
   if(seq!==generation||e?.name==='AbortError')return;
   console.warn('S.C.O.T.T.Y. Scottish voice',e);
   state('BUSY');setCommand('SCOTTISH VOICE BUSY');
   const msg=$('#voiceMsg');if(msg)msg.textContent='Scottish voice: '+String(e?.message||e).slice(0,180);
  }finally{
   if(seq===generation){if(progressTimer){clearInterval(progressTimer);progressTimer=null}active=null;speaking=false;try{clearVoiceBuffers()}catch{}}
  }
 };
  const previousCommand=command;
  command=async function(t){
    const n=String(t||'').toLowerCase().replace(/[.!?]+$/,'').trim();
    if(/^(approve|approved|approve it|yes approve|yes approved)$/.test(n)){
      try{
        document.querySelector('#cs').textContent='CHECKING APPROVAL';
        const p=await api('/api/approvals?status=pending');
        const list=(p.approvals||[]).slice().sort((a,b)=>Date.parse(b.createdAt||0)-Date.parse(a.createdAt||0));
        if(!list.length){await speak('There is no pending action waiting for approval.');return}
        const newest=list[0];
        const age=Date.now()-Date.parse(newest.createdAt||0);
        if(!(age>=0&&age<15*60*1000)){await speak('The pending actions are not recent enough for me to guess. Open Live Ops and choose the action.');return}
        document.querySelector('#cs').textContent='APPROVING ACTION';
        await api('/api/approvals/'+encodeURIComponent(newest.id)+'/approve',{method:'POST',body:'{}'});
        document.querySelector('#cs').textContent='EXECUTING APPROVED ACTION';
        const r=await api('/api/missions/'+encodeURIComponent(newest.missionId)+'/run',{method:'POST',body:'{}'});
        const last=(r.steps||[]).slice(-1)[0];
        const st=r?.mission?.status||'';
        if(st==='completed'||last?.status==='completed') await speak('Approved and completed. '+String(last?.result||'The action finished successfully.'));
        else if(st==='needs_attention'||last?.status==='error') await speak('I approved it, but the provider action needs attention. '+String(last?.result||'Please check Live Ops.'));
        else await speak('Approved. I am continuing the mission.');
        return;
      }catch(e){
        console.warn('S.C.O.T.T.Y. approval',e);
        document.querySelector('#cs').textContent='APPROVAL ERROR';
        return;
      }
    }
    return previousCommand(t);
  };


 function updateVoicePanel(){
  const panel=$('#voiceSettings');if(!panel)return;
  const label=panel.querySelector('label');if(label)label.textContent='Voice provider: free local Scottish voice';
  const input=$('#elVoiceId');if(input){input.style.display='none';const l=input.previousElementSibling;if(l&&l.tagName==='LABEL')l.style.display='none'}
  const oldLibrary=$('#scottyElevenVoiceLibrary');if(oldLibrary)oldLibrary.style.display='none';
  const save=$('#saveVoice');if(save){save.style.display='none'}
  const msg=$('#voiceMsg');if(msg)msg.textContent='Scottish F5 voice connected through the Eyes On test bridge. No ElevenLabs credits or voice ID needed. Tap TEST to listen.';
  const test=$('#testVoice');if(test){test.textContent='TEST SCOTTISH VOICE'}
 }
 const badge=document.createElement('span');badge.id='scottyVoiceQueueStatus';badge.textContent='VOICE: READY';badge.style.cssText='display:inline-block;border:1px solid #28616a;border-radius:8px;padding:5px 8px;color:#92e8e1;font-size:10px;letter-spacing:.08em';const header=document.querySelector('header')||document.querySelector('#vs')?.parentElement;if(header)header.appendChild(badge);
 const preview=document.createElement('button');
 preview.id='scottyScottishPreview';preview.textContent='▶ HEAR SCOTTISH VOICE NOW';
 preview.style.cssText='width:100%;margin-top:8px;background:#12313b;color:#b8f9f0;border:1px solid #58a8b1;padding:10px;border-radius:8px;font-weight:bold';
 preview.onclick=async()=>{
  try{
   const r=await fetch('/api/voice/scottish/ack',{credentials:'include'});
   if(!r.ok)throw await responseError(r);
   const blob=await r.blob(),url=URL.createObjectURL(blob),a=new Audio(url);
   a.onended=()=>URL.revokeObjectURL(url);
   a.onerror=()=>URL.revokeObjectURL(url);
   await a.play();
  }catch(e){const msg=$('#voiceMsg');if(msg)msg.textContent='Scottish preview: '+String(e?.message||e)}
 };
 const panel=$('#voiceSettings');if(panel)panel.appendChild(preview);
 const modeButton=document.createElement('button');modeButton.id='scottyVoiceMode';modeButton.style.cssText='width:100%;margin-top:8px;background:#12313b;color:#b8f9f0;border:1px solid #58a8b1;padding:10px;border-radius:8px';
 function updateMode(){modeButton.textContent=voiceMode==='fast'?'MODE: FAST (DEVICE VOICE) • SWITCH TO SCOTTISH F5':'MODE: SCOTTISH F5 (SLOW) • SWITCH TO FAST';const msg=$('#voiceMsg');if(msg)msg.textContent=voiceMode==='fast'?'Fast mode speaks using the iPad built-in voice; a Scottish accent is not guaranteed. No paid API or F5 queue.':'Scottish F5 mode preserves the custom voice but may take minutes on the Windows CPU.'}
 modeButton.onclick=()=>{voiceMode=voiceMode==='fast'?'f5':'fast';++generation;stopCurrent();speaking=false;state('READY');updateMode()};
 const voicePanel=$('#voiceSettings');if(voicePanel)voicePanel.appendChild(modeButton);
 updateVoicePanel();updateMode();
 const settings=$('#voiceSettingsBtn');if(settings)settings.addEventListener('click',()=>setTimeout(updateVoicePanel,0));
 state('READY');
})();